  }

  const result: string[] = [];

  for (let r = 0; r < rows; r++) {
    let newRow = "";
    for (let c = 0; c < cols; c++) {
      const cell = field[r][c];
      if (cell === "*") {
        newRow += "*";
      } else {
        let mineCount = 0;
        // Check all 8 neighbors
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
