export function clean(input: string): string {
  // Remove all non-digit characters
  const digits = input.replace(/\D/g, "");

  // Check if the result is exactly 10 digits
  if (digits.length !== 10) {
    throw new Error("Incorrect number of digits");
  }

  // Check for country code '1' if the number is 11 digits
  if (digits.length === 11) {
    if (digits[0] === "1") {
      return digits.slice(1);
    }
    throw new Error("11 digits must start with 1");
  }

  // Validate area code and exchange code (must start with 2-9)
  const areaCode = digits.slice(0, 3);
  const exchangeCode = digits.slice(3, 6);

  if (areaCode[0] < "2" || areaCode[0] > "9") {
    throw new Error("Area code cannot start with zero or one");
  }
  if (exchangeCode[0] < "2" || exchangeCode[0] > "9") {
    throw new Error("Exchange code cannot start with zero or one");
  }

  return digits;
}

