export const translate: TranslateFn = (phrase) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  return phrase.split(' ').map(word => {
      if (word.length === 0) return word;
      if (vowels.has(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
        return word + 'ay';
      }
      let i = 0;
      while (i < word.length && (!vowels.has(word[i]) || (word[i] === 'q' && word[i + 1] === 'u'))) {
        i++;
      }
      if (word[i] === 'y' && i > 0) {
        i--;
      }
      return word.slice(i) + word.slice(0, i) + 'ay';
    }).join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);

  function isVowel(char: string): boolean {
    return vowels.has(char.toLowerCase());
  }

  function translateWord(word: string): string {
    const lowerWord = word.toLowerCase();
    const len = lowerWord.length;

    // Rule 1: Starts with vowel, "xr", or "yt"
    if (isVowel(lowerWord[0]) || lowerWord.startsWith("xr") || lowerWord.startsWith("yt")) {
      return word + "ay";
    }

    // Find the split point for consonants
    let i = 0;
    while (i < len) {
      const char = lowerWord[i];

      // Rule 3: Check for "qu"
      if (char === 'q' && i + 1 < len && lowerWord[i + 1] === 'u') {
        // Move everything up to and including "qu" to the end
        const prefix = lowerWord.substring(0, i + 2);
        const suffix = lowerWord.substring(i + 2);
        return suffix + prefix + "ay";
      }

      // Rule 4: Check for "y" acting as a vowel after consonants
      // "y" is treated as a vowel if it follows consonants and is not at the start (handled by Rule 1 if start)
      if (char === 'y' && i > 0) {
        // Move preceding consonants to the end
        const prefix = lowerWord.substring(0, i);
        const suffix = lowerWord.substring(i);
        return suffix + prefix + "ay";
      }

      // If it's a vowel, stop here (Rule 2 logic)
      if (isVowel(char)) {
        break;
      }

      i++;
    }

    // Rule 2: Move initial consonants to the end
    const prefix = lowerWord.substring(0, i);
    const suffix = lowerWord.substring(i);
    return suffix + prefix + "ay";
  }

  return phrase
    .split(' ')
    .map(translateWord)
    .join(' ');
}

