export function count(rows: string[]): number {
  if (rows.length === 0) return 0;
  const width = rows[0].length;
  if (width === 0) return 0;

  // Validate all rows have the same length and contain only valid characters
  for (const row of rows) {
    if (row.length !== width) return 0;
    if (!/^[ \+|]+$/.test(row)) return 0;
  }

  const height = rows.length;
  const corners: Set<string> = new Set();

  // Identify all '+' positions
  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      if (rows[r][c] === '+') {
        corners.add(`${r},${c}`);
      }
    }
  }

  let rectangleCount = 0;

  // Iterate over every pair of corners to see if they can form opposite corners of a rectangle
  const cornersArray = Array.from(corners);
  for (let i = 0; i < cornersArray.length; i++) {
    for (let j = i + 1; j < cornersArray.length; j++) {
      const [r1, c1] = cornersArray[i].split(',').map(Number);
      const [r2, c2] = cornersArray[j].split(',').map(Number);

      // Check if corners share the same row or column
      if (r1 !== r2 && c1 !== c2) continue;

      // Determine the other two corners needed to complete the rectangle
      let r3, c3, r4, c4;

      if (r1 === r2) {
        // Same row: need corners at (r1, c2) and (r2, c1) -> (r1, c2) and (r1, c1) is same as start, so (r1, c2) and (r1, c1) is wrong logic.
        // Actually if r1 == r2, we need (r1, c2) and (r1, c1) is not right.
        // Points are (r1, c1) and (r1, c2). We need (r1, c1) and (r1, c2) are on same row.
        // We need (r1, c1) and (r1, c2) -> other corners are (r1, c1) [already have] and (r1, c2) [already have].
        // Wait, if r1 == r2, they are on the same row. The other two corners must be on the same row too? No.
        // If two corners are on the same row, the rectangle must be horizontal? No, a rectangle has 4 corners.
        // If (r1, c1) and (r1, c2) are corners, they share a row. The other two corners must be at (r1, c1) and (r1, c2)? No.
        // If two corners share a row, they must be opposite corners? No, opposite corners share neither row nor column.
        // Adjacent corners share one coordinate.
        // If r1 == r2, they are on the same row. They could be adjacent (sharing column) or opposite (sharing row and column? Impossible).
        // If they share row and column, they are the same point.
        // So if r1 == r2, they must share a column to be adjacent? But we iterate unique pairs.
        // If r1 == r2 and c1 != c2, they are on the same row. They cannot be opposite corners of a rectangle unless the rectangle has height 0, which is invalid.
        // Wait, opposite corners of a rectangle (r1, c1) and (r2, c2) must satisfy r1 != r2 AND c1 != c2.
        // So if r1 == r2 or c1 == c2, they are adjacent corners, not opposite.
        // My logic above "if r1 !== r2 && c1 !== c2" correctly filters for opposite corners.
        // So if we pass that check, we have opposite corners.
        // Let's re-evaluate the logic inside the loop.
      }
    }
  }

  // Corrected logic:
  // We need to find pairs of '+' that are opposite corners.
  // Opposite corners (r1, c1) and (r2, c2) must satisfy r1 != r2 and c1 != c2.
  // Then the other two corners must be (r1, c2) and (r2, c1).
  // We check if those two points exist in the 'corners' set.

  for (let i = 0; i < cornersArray.length; i++) {
    for (let j = i + 1; j < cornersArray.length; j++) {
      const [r1, c1] = cornersArray[i].split(',').map(Number);
      const [r2, c2] = cornersArray[j].split(',').map(Number);

      if (r1 === r2 || c1 === c2) continue; // Not opposite corners

      const r3 = r1;
      const c3 = c2;
      const r4 = r2;
      const c4 = c1;

      const key3 = `${r3},${c3}`;
      const key4 = `${r4},${c4}`;

      if (corners.has(key3) && corners.has(key4)) {
        rectangleCount++;
      }
    }
  }

  return rectangleCount;
}

