export function verse(n: number): string {
  const animals = [
    "fly",
    "spider",
    "bird",
    "cat",
    "dog",
    "goat",
    "cow",
    "horse",
  ];

  const reactions = [
    "",
    "It wriggled and jiggled and tickled inside her.",
    "How absurd to swallow a bird!",
    "Imagine that, to swallow a cat!",
    "What a hog, to swallow a dog!",
    "Just opened her throat and swallowed a goat!",
    "I don't know how she swallowed a cow!",
    "She's dead, of course!",
  ];

  const animal = animals[n - 1];
  const reaction = reactions[n - 1];

  let lines: string[] = [];

  lines.push(`I know an old lady who swallowed a ${animal}.`);

  if (n === 1 || n === 8) {
    lines.push(reaction);
  } else if (reaction !== "") {
    lines.push(reaction);
  }

  if (n > 1) {
    let current = n;
    while (current > 1) {
      const prev = current - 1;
      const prevAnimal = animals[prev - 1];
      let line = `She swallowed the ${animals[current - 1]} to catch the ${prevAnimal}.`;

      if (prevAnimal === "spider") {
        line += " that wriggled and jiggled and tickled inside her.";
      }

      lines.push(line);
      current = prev;
    }
  }

  lines.push("I don't know why she swallowed the fly. Perhaps she'll die.");

  return lines.join("\n") + "\n";
}

export function verses(start: number, end: number): string {
