// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  const maxLen = rows.reduce((max, row) => Math.max(max, row.length), 0);
  const cols = Array.from({ length: maxLen }, (_, i) => rows.map(row => row[i] ?? ' '));
  return cols.map(row => row.join(''));
};
// @openarc:end transpose.transpose

export function transpose(rows: string[]): string[] {
  if (rows.length === 0) {
    return [];
  }

  const maxLen = Math.max(...rows.map((row) => row.length));

  const paddedRows = rows.map((row) => {
    const padding = " ".repeat(maxLen - row.length);
    return row + padding;
  });

  const numCols = maxLen;
  const numRows = paddedRows.length;

  const result: string[] = [];

  for (let col = 0; col < numCols; col++) {
    let rowStr = "";
    for (let row = 0; row < numRows; row++) {
      rowStr += paddedRows[row][col];
    }
    result.push(rowStr);
  }

  return result;
}

