export function recite(startVerse: number, endVerse: number): string {
  const gifts = [
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const days = [
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
  ];

  const lines: string[] = [];

  for (let i = startVerse; i <= endVerse; i++) {
    const dayIndex = i - 1;
    let verse = `On the ${days[dayIndex]} day of Christmas my true love gave to me: `;

    for (let j = dayIndex; j >= 0; j--) {
      const gift = gifts[j];
      if (j === 0 && dayIndex > 0) {
        verse += "and ";
      }
      if (j === 0 && dayIndex === 0) {
        verse += gift;
      } else {
        verse += `${gift}, `;
      }
    }

    // Remove the trailing comma and space for the last item if it exists
    if (dayIndex > 0) {
      verse = verse.replace(/, $/, "");
    }

    lines.push(verse + ".\n");
  }

  return lines.join("");
}

