// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let current: number = 0;
    for (let byte of bytes) {
      current = (current << 7) | (byte & 0x7f);
      if ((byte & 0x80) === 0) {
        result.push(current);
        current = 0;
      }
    }
    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Value out of range");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    let value = num;
    let bytes: number[] = [];

    while (value > 0x7F) {
      bytes.unshift((value & 0x7F) | 0x80);
      value >>= 7;
    }

    bytes.unshift(value & 0x7F);
    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  if (bytes.length === 0) {
    return [];
  }

  const result: number[] = [];
  let current: number = 0;
  let shift = 0;

  for (const byte of bytes) {
    if (byte < 0 || byte > 0xFF) {
      throw new Error("Invalid byte value");
    }

    if (byte & 0x80) {
      if (shift > 28) {
        throw new Error("Value out of range");
      }
      current |= (byte & 0x7F) << shift;
      shift += 7;
    } else {
      if (shift > 21) {
        throw new Error("Value out of range");
      }
      current |= (byte & 0x7F) << shift;
      shift += 7;
      result.push(current);
      current = 0;
      shift = 0;
    }
  }

  if (shift > 0) {
    throw new Error("Incomplete sequence");
  }

  return result;
}

