export function answer(question: string): number {
  if (!question.startsWith("What is ")) {
    throw new Error("Unknown operation");
  }

  const expression = question.slice(9, -1).trim();
  if (!expression) {
    throw new Error("Unknown operation");
  }

  const tokens = expression.split(/\s+/);
  if (tokens.length === 0) {
    throw new Error("Unknown operation");
  }

  let currentNumber: number | null = null;
  let index = 0;

  // Parse the first number
  if (!/^-?\d+(\.\d+)?$/.test(tokens[0])) {
    throw new Error("Unknown operation");
  }
  currentNumber = parseFloat(tokens[0]);

  while (index < tokens.length - 1) {
    const op = tokens[++index];
    const nextToken = tokens[++index];

    if (!/^(plus|minus|multiplied by|divided by)$/.test(op)) {
      throw new Error("Unknown operation");
    }

    if (!/^-?\d+(\.\d+)?$/.test(nextToken)) {
      throw new Error("Unknown operation");
    }

    const nextNumber = parseFloat(nextToken);

    switch (op) {
      case "plus":
        currentNumber += nextNumber;
        break;
      case "minus":
        currentNumber -= nextNumber;
        break;
      case "multiplied by":
        currentNumber *= nextNumber;
        break;
      case "divided by":
        if (nextNumber === 0) {
          throw new Error("Unknown operation");
        }
        currentNumber /= nextNumber;
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  if (currentNumber === null) {
    throw new Error("Unknown operation");
  }

  return Math.round(currentNumber);
}

