// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  if (digits.length === 0) return [];
  const value = digits.reduce((acc, d) => acc * inputBase + d, 0);
  if (value === 0) return [0];
  const result: number[] = [];
  let current = value;
  while (current > 0) {
    result.unshift(current % outputBase);
    current = Math.floor(current / outputBase);
  }
  return result;
};
// @openarc:end allYourBase.convert

export function convert(digits: number[], inputBase: number, outputBase: number): number[] {
  // Validate inputBase
  if (inputBase <= 1 || !Number.isInteger(inputBase)) {
    throw new Error("Wrong input base");
  }

  // Validate outputBase
  if (outputBase <= 1 || !Number.isInteger(outputBase)) {
    throw new Error("Wrong output base");
  }

  // Validate digits array
  if (digits.length === 0) {
    return [];
  }

  if (digits.length > 1 && digits[0] === 0) {
    throw new Error("Input has wrong format");
  }

  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase || !Number.isInteger(digit)) {
      throw new Error("Input has wrong format");
    }
  }

  // Convert from inputBase to base 10 (decimal)
  let decimalValue = 0;
  for (const digit of digits) {
    decimalValue = decimalValue * inputBase + digit;
  }

  // Handle the zero case
  if (decimalValue === 0) {
    return [0];
  }

  // Convert from base 10 to outputBase
  const result: number[] = [];
  let tempValue = decimalValue;

  while (tempValue > 0) {
    const remainder = tempValue % outputBase;
    result.unshift(remainder);
    tempValue = Math.floor(tempValue / outputBase);
  }

  return result;
}

