export const makeDiamond: MakeDiamondFn = (character) => {
  const code = character.charCodeAt(0) - 'A'.charCodeAt(0);
    const lines = [];
    for (let i = 0; i <= code; i++) {
      const line = [];
      for (let j = 0; j < code - i; j++) line.push(' ');
      line.push(String.fromCharCode('A'.charCodeAt(0) + i));
      for (let j = 0; j < i; j++) line.push(' ');
      if (i > 0) {
        line.push(String.fromCharCode('A'.charCodeAt(0) + i));
        for (let j = 0; j < i; j++) line.push(' ');
      }
      for (let j = 0; j < code - i; j++) line.push(' ');
      lines.push(line.join(''));
    }
    for (let i = code - 1; i >= 0; i--) {
      lines.push(lines[i + 1]);
    }
    return lines.join('\n') + '\n';
};
// @openarc:end diamond.makeDiamond

export function makeDiamond(character: string): string {
  const targetIndex = character.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);

  if (targetIndex < 0 || targetIndex > 25) {
    throw new Error("Input character must be between 'A' and 'Z'");
  }

  const lines: string[] = [];

  // Top half including the middle line
  for (let i = 0; i <= targetIndex; i++) {
    const char = String.fromCharCode('A'.charCodeAt(0) + i);
    const spaces = " ".repeat(targetIndex - i);
    if (i === 0) {
      lines.push(spaces + char + spaces);
    } else {
      const innerSpaces = " ".repeat(2 * i - 1);
      lines.push(spaces + char + innerSpaces + char + spaces);
    }
  }

  // Bottom half (mirror of top, excluding the middle line)
  for (let i = targetIndex - 1; i >= 0; i--) {
    const char = String.fromCharCode('A'.charCodeAt(0) + i);
    const spaces = " ".repeat(targetIndex - i);
    if (i === 0) {
      lines.push(spaces + char + spaces);
    } else {
      const innerSpaces = " ".repeat(2 * i - 1);
      lines.push(spaces + char + innerSpaces + char + spaces);
    }
  }

  return lines.join("\n") + "\n";
}

