// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const grid = rows;
  const h = grid.length;
  if (h === 0) return 0;
  const w = grid[0].length;
  if (w === 0) return 0;
  const corners = new Set<string>();
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (grid[r][c] === '+') {
        corners.add(`${r},${c}`);
      }
    }
  }
  let count = 0;
  for (let r1 = 0; r1 < h; r1++) {
    for (let c1 = 0; c1 < w; c1++) {
      if (!corners.has(`${r1},${c1}`)) continue;
      for (let r2 = r1; r2 < h; r2++) {
        for (let c2 = c1; c2 < w; c2++) {
          if (r1 === r2 && c1 === c2) continue;
          const topRight = `${r1},${c2}`;
          const bottomLeft = `${r2},${c1}`;
          const bottomRight = `${r2},${c2}`;
          if (corners.has(topRight) && corners.has(bottomLeft) && corners.has(bottomRight)) {
            count++;
          }
        }
      }
    }
  }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (rows.length === 0) return 0;
  const width = rows[0].length;
  if (width === 0) return 0;

  // Validate all rows have the same length and contain only valid characters
  for (const row of rows) {
    if (row.length !== width) return 0;
    if (!/^[ \+|]+$/.test(row)) return 0;
  }

  const height = rows.length;
  const corners: Set<string> = new Set();

  // Identify all '+' positions
  for (let r = 0; r < height; r++) {
    for (let c = 0; c < width; c++) {
      if (rows[r][c] === '+') {
        corners.add(`${r},${c}`);
      }
    }
  }

  let rectangleCount = 0;

  // Iterate over every pair of corners to see if they can form opposite corners of a rectangle
  const cornersArray = Array.from(corners);
  for (let i = 0; i < cornersArray.length; i++) {
    for (let j = i + 1; j < cornersArray.length; j++) {
      const [r1, c1] = cornersArray[i].split(',').map(Number);
      const [r2, c2] = cornersArray[j].split(',').map(Number);

      // Check if corners share the same row or column
      if (r1 !== r2 && c1 !== c2) continue;

      // Determine the other two corners needed to complete the rectangle
      let r3, c3, r4, c4;

      if (r1 === r2) {
        // Same row: need corners at (r1, c2) and (r2, c1) -> (r1, c2) and (r1, c1) is same as start, so (r1, c2) and (r1, c1) is wrong logic.
        // Actually if r1 == r2, we need (r1, c2) and (r1, c1) is not right.
        // Points are (r1, c1) and (r1, c2). We need (r1, c1) and (r1, c2) are on same row.
        // We need (r1, c1) and (r1, c2) -> other corners are (r1, c1) [already have] and (r1, c2) [already have].
        // Wait, if r1 == r2, they are on the same row. The other two corners must be on the same row too? No.
        // If two corners share a row, the rectangle must be horizontal? No, a rectangle has 4 corners.
        // If (r1, c1) and (r1, c2) are corners, they share a row. The other two corners must be at (r1, c1) and (r1, c2)? No.
        // If they are opposite, they must share neither row nor column. So r1 != r2 and c1 != c2.
        // Therefore, if r1 == r2, they cannot be opposite corners. They must be adjacent corners sharing a row.
        // But we are looking for rectangles defined by opposite corners.
        // So we only care if r1 != r2 AND c1 != c2.
        // My previous check `if (r1 !== r2 && c1 !== c2) continue;` handles this.
        // So if we are here, one coordinate matches and the other differs.
      }

      // Case 1: Same row (r1 == r2) -> Impossible for opposite corners.
      // Case 2: Same column (c1 == c2) -> Impossible for opposite corners.
      // So we must have r1 != r2 and c1 != c2.
      // The other two corners are (r1, c2) and (r2, c1).

      const r3 = r1;
      const c3 = c2;
      const r4 = r2;
      const c4 = c1;

      const key1 = `${r3},${c3}`;
      const key2 = `${r4},${c4}`;

      if (corners.has(key1) && corners.has(key2)) {
        rectangleCount++;
      }
    }
  }

  return rectangleCount;
}

