export const recite: ReciteFn = (startVerse, endVerse) => arc.todo("twelveDays.recite");
// @openarc:end twelveDays.recite

export function recite(startVerse: number, endVerse: number): string {
  if (startVerse < 1 || endVerse > 12 || startVerse > endVerse) {
    throw new Error("Invalid verse range");
  }

  const gifts = [
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const days = [
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
  ];

  const verses: string[] = [];

  for (let i = startVerse; i <= endVerse; i++) {
    const currentGifts = gifts.slice(0, i);
    let verseText = `On the ${days[i - 1]} day of Christmas my true love gave to me: `;

    // Build the list of gifts in reverse order
    for (let j = i - 1; j >= 0; j--) {
      if (i > 1 && j === 0) {
        // Special case for the first gift when there are multiple days
        verseText += `and ${currentGifts[j]}`;
      } else {
        verseText += `${currentGifts[j]}, `;
      }
    }

    // Remove the trailing comma and space if it exists
    verseText = verseText.slice(0, -2) + ".";

    verses.push(verseText + "\n");
  }

  return verses.join("");
}

