export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let i = 0;
    while (i < bytes.length) {
      let byte = bytes[i];
      let value = byte & 0x7F;
      i++;
      while (byte & 0x80) {
        byte = bytes[i];
        value = (value << 7) | (byte & 0x7F);
        i++;
      }
      result.push(value);
    }
    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit (0x80) for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let isContinuing = false;

  for (const byte of bytes) {
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    if (isContinuing) {
      currentNumber = (currentNumber << 7) | (byte & 0x7F);
    } else {
      if ((byte & 0x80) === 0) {
        // Last byte (continuation bit is 0)
        result.push(byte);
      } else {
        // Not the last byte (continuation bit is 1)
        currentNumber = byte & 0x7F;
        isContinuing = true;
      }
    }
  }

  if (isContinuing) {
    throw new Error("Incomplete sequence: last byte had continuation bit set");
  }

  return result;
}

