// @openarc:end wordy.answer

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Invalid question");
  }

  const trimmed = question.trim();
  if (!trimmed.startsWith("What is")) {
    throw new Error("Unknown operation");
  }

  const expression = trimmed
    .substring(7) // length of "What is"
    .trim()
    .replace(/\?$/, "");

  if (!expression) {
    throw new Error("Syntax error");
  }

  const tokens = tokenize(expression);
  let result: number;
  let index = 0;

  // First number
  const firstToken = tokens[index++];
  if (!isNumberToken(firstToken)) {
    throw new Error("Syntax error");
  }
  result = parseFloat(firstToken);

  // Process remaining tokens
  while (index < tokens.length) {
    const opToken = tokens[index];
    const nextToken = tokens[index + 1];

    if (!isOperator(opToken)) {
      throw new Error("Syntax error");
    }

    index++; // move past operator

    if (!isNumberToken(nextToken)) {
      throw new Error("Syntax error");
    }

    const operand = parseFloat(nextToken);
    index++; // move past operand

    let newResult: number;
    switch (opToken) {
      case "plus":
        newResult = result + operand;
        break;
      case "minus":
        newResult = result - operand;
        break;
      case "multiplied by":
        newResult = result * operand;
        break;
      case "divided by":
        if (operand === 0) {
          throw new Error("Division by zero");
        }
        newResult = result / operand;
        break;
      default:
        throw new Error("Unknown operation");
    }

    result = newResult;
  }

  // Check if we consumed all tokens
  if (index !== tokens.length) {
    throw new Error("Syntax error");
  }

  return Math.round(result);
}

function tokenize(input: string): string[] {
  const tokens: string[] = [];
  let current = "";
  let i = 0;

  while (i < input.length) {
    const char = input[i];

    if (/\s/.test(char)) {
      if (current) {
        tokens.push(current);
        current = "";
      }
      i++;
      continue;
    }

    if (char === "?") {
      if (current) {
        tokens.push(current);
        current = "";
      }
      i++;
      continue;
    }

    current += char;
    i++;
  }

  if (current) {
    tokens.push(current);
  }

  // Post-process to split multi-word operators
  const finalTokens: string[] = [];
  let i = 0;
  while (i < tokens.length) {
    const token = tokens[i];
    if (
      token === "multiplied" &&
      i + 1 < tokens.length &&
      tokens[i + 1] === "by"
    ) {
      finalTokens.push("multiplied by");
      i += 2;
    } else if (
      token === "divided" &&
      i + 1 < tokens.length &&
      tokens[i + 1] === "by"
    ) {
      finalTokens.push("divided by");
      i += 2;
    } else {
      finalTokens.push(token);
      i++;
    }
  }

  return finalTokens;
}

function isNumberToken(token: string): boolean {
  return /^-?\d+(\.\d+)?$/.test(token);
}

function isOperator(token: string): boolean {
  return (
    token === "plus" ||
    token === "minus" ||
    token === "multiplied by" ||
    token === "divided by"
  );
}

