export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let value = 0;
    let shift = 0;
    for (const byte of bytes) {
      value = (value << 7) | (byte & 0x7f);
      shift += 7;
      if ((byte & 0x80) === 0) {
        result.push(value);
        value = 0;
        shift = 0;
      }
    }
    return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit (0x80) for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let isContinuing = false;

  for (const byte of bytes) {
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    if (isContinuing) {
      currentNumber = (currentNumber << 7) | (byte & 0x7F);
    } else {
      if ((byte & 0x80) === 0) {
        // This is a single byte number (no continuation bit set)
        result.push(byte);
      } else {
        // This is a continuation byte, start accumulating
        currentNumber = byte & 0x7F;
        isContinuing = true;
      }
    }

    // Check for overflow: if we have accumulated more than 32 bits, it's an error.
    // We can check this by seeing if the number exceeds 0xFFFFFFFF.
    // However, we must be careful: intermediate values might be large but valid if we haven't finished.
    // Actually, if we have 5 continuation bytes, the max value is 0xFFFFFFFF.
    // If we have 6 continuation bytes, the value will be > 0xFFFFFFFF.
    // So checking > 0xFFFFFFFF is safe.
    if (currentNumber > 0xFFFFFFFF) {
      throw new Error("Number exceeds 32-bit unsigned integer range");
    }
  }

  // If we ended with a continuing sequence, it's an error
  if (isContinuing) {
    throw new Error("Incomplete sequence: missing final byte");
  }

  return result;
}

