// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count === 0 ? ' ' : String(count));
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  if (field.length === 0) {
    return [];
  }

  const rows = field.length;
  const cols = field[0].length;

  // Handle rows that might be shorter than the first row (though not expected based on problem description)
  const minCols = Math.min(...field.map((row) => row.length));
  const maxCols = Math.max(...field.map((row) => row.length));

  // If all rows are empty strings, return as is
  if (minCols === 0) {
    return field;
  }

  const result: string[] = [];

  for (let r = 0; r < rows; r++) {
    let newRow = "";
    const rowStr = field[r];
    const rowLen = rowStr.length;

    for (let c = 0; c < rowLen; c++) {
      const cell = rowStr[c];

      if (cell === '*') {
        newRow += '*';
        continue;
      }

      // Count adjacent mines
      let mineCount = 0;

      // Check all 8 directions
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if (dr === 0 && dc === 0) continue;

          const nr = r + dr;
          const nc = c + dc;

          // Check bounds
          if (nr >= 0 && nr < rows && nc >= 0 && nc < field[nr].length) {
            if (field[nr][nc] === '*') {
              mineCount++;
            }
          }
        }
      }

      if (mineCount > 0) {
        newRow += mineCount.toString();
      } else {
        newRow += ' ';
      }
    }

    result.push(newRow);
  }

  return result;
}

