import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": [
    "Exercise \"phone-number\": implement `clean`.",
    "Clean up phone numbers so that they can be sent SMS messages.",
    "The **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda. All NANP-countries share the same international country code: `1`.",
    "NANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number. The first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.",
    "The format is usually represented as",
    "```text NXX NXX-XXXX ```",
    "where `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.",
    "Sometimes they also have the country code (represented as `1` or `+1`) prefixed.",
    "Your task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.",
    "For example, the inputs",
    "- `+1 (613)-995-0253` - `613-995-0253` - `1 613 995 0253` - `613.995.0253`",
    "should all produce the output",
    "`6139950253`",
    "**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code."
  ],
  "examples": [
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans the number",
      "args": [
        "(223) 456-7890"
      ],
      "expected": "2234567890"
    },
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans numbers with dots",
      "args": [
        "223.456.7890"
      ],
      "expected": "2234567890"
    }
  ]
});

// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => {
  const cleaned = input.replace(/[\s\-\(\)\+\.]/g, '');
    if (cleaned.length === 11 && cleaned.startsWith('1')) {
      return cleaned.slice(1);
    }
    if (cleaned.length === 10) {
      return cleaned;
    }
    throw new Error('Invalid phone number');
};
// @openarc:end phoneNumber.clean

export function clean(input: string): string {
  // Remove all non-digit characters
  const digits = input.replace(/\D/g, "");

  // Handle country code
  if (digits.length === 11) {
    if (digits[0] !== "1") {
      throw new Error("11 digits must start with 1");
    }
    digits = digits.slice(1);
  }

  // Validate length after removing country code
  if (digits.length !== 10) {
    throw new Error("Incorrect phone number length");
  }

  // Validate area code (first digit must be 2-9)
  if (digits[0] < "2" || digits[0] > "9") {
    throw new Error("Area code cannot start with zero or one");
  }

  // Validate exchange code (fourth digit must be 2-9)
  if (digits[3] < "2" || digits[3] > "9") {
    throw new Error("Exchange code cannot start with zero or one");
  }

  return digits;
}

import * as arc from "open-arc";

export type TranslateFn = (phrase: string) => string;

export const translateSpec = arc.defineRegion<TranslateFn>({
  "id": "pigLatin.translate",
  "intent": [
    "Exercise \"pig-latin\": implement `translate`.",
    "Your task is to translate text from English to Pig Latin. The translation is defined using four rules, which look at the pattern of vowels and consonants at the beginning of a word. These rules look at each word's use of vowels and consonants:",
    "- vowels: the letters `a`, `e`, `i`, `o`, and `u` - consonants: the other 21 letters of the English alphabet",
    "## Rule 1",
    "If a word begins with a vowel, or starts with `\"xr\"` or `\"yt\"`, add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"apple\"` -> `\"appleay\"` (starts with vowel) - `\"xray\"` -> `\"xrayay\"` (starts with `\"xr\"`) - `\"yttria\"` -> `\"yttriaay\"` (starts with `\"yt\"`)",
    "## Rule 2",
    "If a word begins with one or more consonants, first move those consonants to the end of the word and then add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"pig\"` -> `\"igp\"` -> `\"igpay\"` (starts with single consonant) - `\"chair\"` -> `\"airch\"` -> `\"airchay\"` (starts with multiple consonants) - `\"thrush\"` -> `\"ushthr\"` -> `\"ushthray\"` (starts with multiple consonants)",
    "## Rule 3",
    "If a word starts with zero or more consonants followed by `\"qu\"`, first move those consonants (if any) and the `\"qu\"` part to the end of the word, and then add an `\"ay\"` sound to the end of the word.",
    "For example:",
    "- `\"quick\"` -> `\"ickqu\"` -> `\"ickquay\"` (starts with `\"qu\"`, no preceding consonants) - `\"square\"` -> `\"aresqu\"` -> `\"aresquay\"` (starts with one consonant followed by `\"qu`\")",
    "## Rule 4",
    "If a word starts with one or more consonants followed by `\"y\"`, first move the consonants preceding the `\"y\"`to the end of the word, and then add an `\"ay\"` sound to the end of the word.",
    "Some examples:",
    "- `\"my\"` -> `\"ym\"` -> `\"ymay\"` (starts with single consonant followed by `\"y\"`) - `\"rhythm\"` -> `\"ythmrh\"` -> `\"ythmrhay\"` (starts with multiple consonants followed by `\"y\"`)"
  ],
  "examples": [
    {
      "name": "ay is added to words that start with vowels > word beginning with a",
      "args": [
        "apple"
      ],
      "expected": "appleay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with e",
      "args": [
        "ear"
      ],
      "expected": "earay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with i",
      "args": [
        "igloo"
      ],
      "expected": "iglooay"
    }
  ]
});

// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const translateWord = (word: string): string => {
    if (vowels.has(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
      return word + 'ay';
    }
    let i = 0;
    while (i < word.length) {
      if (word[i] === 'y' && i > 0) {
        break;
      }
      if (word[i] === 'q' && i + 1 < word.length && word[i + 1] === 'u') {
        i += 2;
        continue;
      }
      if (vowels.has(word[i])) {
        break;
      }
      i++;
    }
    return word.slice(i) + word.slice(0, i) + 'ay';
  };
  return phrase.split(' ').map(translateWord).join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  if (!phrase) return phrase;

  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);

  const translateWord = (word: string): string => {
    const lowerWord = word.toLowerCase();

    // Rule 1: Starts with vowel, "xr", or "yt"
    if (
      vowels.has(lowerWord[0]) ||
      (lowerWord.startsWith('xr') && lowerWord.length >= 2) ||
      (lowerWord.startsWith('yt') && lowerWord.length >= 2)
    ) {
      return word + 'ay';
    }

    let i = 0;
    const len = lowerWord.length;

    // Check for "qu" at the start (Rule 3)
    if (lowerWord.startsWith('qu')) {
      return word.slice(2) + 'qu' + 'ay';
    }

    // Find the split point for consonants
    while (i < len) {
      const char = lowerWord[i];

      // Rule 4: 'y' acts as a vowel if preceded by consonants
      if (char === 'y' && i > 0) {
        break;
      }

      // If we hit a vowel (and it's not 'y' at start), stop
      if (vowels.has(char)) {
        break;
      }

      i++;
    }

    // If we went through the whole word without finding a vowel split (e.g., "rhythm" -> 'y' handled above, but if no 'y' found and all consonants)
    // Actually, if loop finishes, i == len.
    // For words like "rhythm", 'y' is at index 2. Loop: i=0 ('r' cons), i=1 ('h' cons), i=2 ('y' -> break). Correct.
    // For words like "string", 'i' is at index 1. Loop: i=0 ('s' cons), i=1 ('t' cons? No, 't' is cons), wait.
    // "string": s(0), t(1), r(2), i(3).
    // i=0: 's' cons -> continue
    // i=1: 't' cons -> continue
    // i=2: 'r' cons -> continue
    // i=3: 'i' vowel -> break.
    // Split at 3. "str" + "ing" -> "ingstray". Correct.

    // Special case: if the word is all consonants (e.g., "gym" -> y is vowel here? No, y at start is consonant usually, but rule 4 says "preceded by consonants".
    // If word is "gym": g(0), y(1). i=0 'g' cons. i=1 'y'. Since i>0, break. Split at 1. "g" + "ym" -> "ymgay". Correct.
    // If word is "my": m(0), y(1). i=0 'm' cons. i=1 'y'. i>0 break. Split at 1. "m" + "y" -> "ymay". Correct.
    // If word is "yttria": starts with 'y'. i=0. char='y'. i>0 is false. vowels.has('y') is false. i increments to 1.
    // i=1: 't'. cons. i=2: 't'. cons. i=3: 'r'. cons. i=4: 'i'. vowel. break.
    // Wait, Rule 1 says "yt" starts with vowel sound. My initial check handled "yt".
    // What about "yacht"? y-a-c-h-t.
    // i=0 'y'. Not vowel. i=1 'a'. Vowel. Break. Split at 1. "y" + "acht" -> "achtway"? No.
    // Rule 4: "If a word starts with one or more consonants followed by 'y'".
    // In "yacht", 'y' is at the start. It is NOT preceded by consonants. So 'y' acts as a consonant here?
    // Standard Pig Latin rules: 'y' is a vowel only if it follows consonants. If it starts the word, it's a consonant.
    // My logic: i=0, char='y'. i>0 is false. vowels.has('y') is false. i becomes 1.
    // i=1, char='a'. vowels.has('a') is true. Break.
    // Split at 1. Prefix "y", suffix "acht". Result "achtway".
    // Is this correct? "yacht" -> "yachtaay"?
    // Let's re-read Rule 4 carefully: "If a word starts with one or more consonants followed by 'y'".
    // This implies the 'y' is the first vowel sound encountered after the consonant cluster.
    // If 'y' is at the very beginning, it is not "followed by" anything in terms of preceding consonants. It is the start.
    // Usually, 'y' at the start is treated as a consonant. So "yacht" -> "yachtaay" (Rule 1 doesn't apply, Rule 2 applies to consonant cluster "yach"? No, 'a' is vowel).
