import * as arc from "open-arc";

export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": [
    "Exercise \"rectangles\": implement `count`.",
    "Count the rectangles in an ASCII diagram like the one below.",
    "```text +--+ ++  | +-++--+ |  |  | +--+--+ ```",
    "The above diagram contains these 6 rectangles:",
    "```text",
    "+-----+ |     | +-----+ ```",
    "```text +--+ |  | |  | |  | +--+ ```",
    "```text +--+ |  | +--+",
    "```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "++ ++",
    "```",
    "You may assume that the input is always a proper rectangle (i.e. the length of every line equals the length of the first line)."
  ],
  "examples": [
    {
      "name": "Rectangles > no rows",
      "args": [
        []
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no rectangles",
      "args": [
        [
          " "
        ]
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const h = rows.length;
  if (h === 0) return 0;
  const w = rows[0].length;
  if (w === 0) return 0;
  const isCorner = (r: number, c: number): boolean => {
      const ch = rows[r][c];
      return ch === '+';
    };
  const isHorizontal = (r: number, c1: number, c2: number): boolean => {
      for (let c = c1; c <= c2; c++) {
        if (rows[r][c] !== '-') return false;
      }
      return true;
    };
  const isVertical = (c: number, r1: number, r2: number): boolean => {
      for (let r = r1; r <= r2; r++) {
        if (rows[r][c] !== '|') return false;
      }
      return true;
    };
  let count = 0;
  for (let r1 = 0; r1 < h; r1++) {
      for (let c1 = 0; c1 < w; c1++) {
        if (!isCorner(r1, c1)) continue;

        for (let r2 = r1; r2 < h; r2++) {
          for (let c2 = c1; c2 < w; c2++) {
            if (!isCorner(r1, c2)) continue;
            if (!isCorner(r2, c1)) continue;
            if (!isCorner(r2, c2)) continue;

            if (isHorizontal(r1, c1, c2) &&
                isHorizontal(r2, c1, c2) &&
                isVertical(c1, r1, r2) &&
                isVertical(c2, r1, r2)) {
              count++;
            }
          }
        }
      }
    }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (!rows || rows.length === 0) return 0;

  const numCols = rows[0].length;
  if (numCols === 0) return 0;

  // Validate that all rows have the same length as the first row
  for (const row of rows) {
    if (row.length !== numCols) {
      throw new Error("All rows must have the same length");
    }
  }

  const numRows = rows.length;
  let rectangleCount = 0;

  // Iterate over all possible top-left corners (r1, c1)
  for (let r1 = 0; r1 < numRows; r1++) {
    for (let c1 = 0; c1 < numCols; c1++) {
      // Top-left corner must be '+'
      if (rows[r1][c1] !== '+') continue;

      // Iterate over all possible bottom-right corners (r2, c2)
      for (let r2 = r1 + 1; r2 < numRows; r2++) {
        for (let c2 = c1 + 1; c2 < numCols; c2++) {
          // Bottom-right corner must be '+'
          if (rows[r2][c2] !== '+') continue;

          // Check the other two corners
          if (rows[r1][c2] !== '+' || rows[r2][c1] !== '+') continue;

          // Check the top edge from (r1, c1) to (r1, c2)
          let topEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (rows[r1][c] !== '-') {
              topEdgeValid = false;
              break;
            }
          }
          if (!topEdgeValid) continue;

          // Check the bottom edge from (r2, c1) to (r2, c2)
          let bottomEdgeValid = true;
          for (let c = c1 + 1; c < c2; c++) {
            if (rows[r2][c] !== '-') {
              bottomEdgeValid = false;
              break;
            }
          }
          if (!bottomEdgeValid) continue;

          // Check the left edge from (r1, c1) to (r2, c1)
          let leftEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (rows[r][c1] !== '|') {
              leftEdgeValid = false;
              break;
            }
          }
          if (!leftEdgeValid) continue;

          // Check the right edge from (r1, c2) to (r2, c2)
          let rightEdgeValid = true;
          for (let r = r1 + 1; r < r2; r++) {
            if (rows[r][c2] !== '|') {
              rightEdgeValid = false;
              break;
            }
          }
          if (!rightEdgeValid) continue;

          // If all edges are valid, we found a rectangle
          rectangleCount++;
        }
      }
    }
  }

  return rectangleCount;
}

import * as arc from "open-arc";

export type OfSizeFn = (size: number) => number[][];

export const ofSizeSpec = arc.defineRegion<OfSizeFn>({
  "id": "spiralMatrix.ofSize",
  "intent": [
    "Exercise \"spiral-matrix\": implement `ofSize`.",
    "Your task is to return a square matrix of a given size.",
    "The matrix should be filled with natural numbers, starting from 1 in the top-left corner, increasing in an inward, clockwise spiral order, like these examples:",
    "## Examples",
    "### Spiral matrix of size 3",
    "```text 1 2 3 8 9 4 7 6 5 ```",
    "### Spiral matrix of size 4",
    "```text 1  2  3 4 12 13 14 5 11 16 15 6 10  9  8 7 ```"
  ],
  "examples": [
    {
      "name": "Spiral Matrix > empty spiral",
      "args": [
        0
      ],
      "expected": []
    },
    {
      "name": "Spiral Matrix > trivial spiral",
      "args": [
        1
      ],
      "expected": [
        [
          1
        ]
      ]
    }
  ]
});

// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  const n = size;
  const matrix = Array.from({ length: n }, () => Array(n).fill(0));
  let num = 1;
  let top = 0, bottom = n - 1, left = 0, right = n - 1;
  while (top <= bottom && left <= right) {
    for (let i = left; i <= right; i++) matrix[top][i] = num++;
    top++;
    for (let i = top; i <= bottom; i++) matrix[i][right] = num++;
    right--;
    if (top <= bottom) {
      for (let i = right; i >= left; i--) matrix[bottom][i] = num++;
      bottom--;
    }
    if (left <= right) {
      for (let i = bottom; i >= top; i--) matrix[i][left] = num++;
      left++;
    }
  }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

export function ofSize(size: number): number[][] {
  if (size === 0) {
    return [];
  }

  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));

  let top = 0;
  let bottom = size - 1;
  let left = 0;
  let right = size - 1;
  let num = 1;

  while (top <= bottom && left <= right) {
    // Traverse from left to right along the top row
    for (let i = left; i <= right; i++) {
      matrix[top][i] = num++;
    }
    top++;

    // Traverse from top to bottom along the right column
    for (let i = top; i <= bottom; i++) {
      matrix[i][right] = num++;
    }
    right--;

    // Traverse from right to left along the bottom row
    if (top <= bottom) {
      for (let i = right; i >= left; i--) {
        matrix[bottom][i] = num++;
      }
      bottom--;
    }

    // Traverse from bottom to top along the left column
    if (left <= right) {
      for (let i = bottom; i >= top; i--) {
        matrix[i][left] = num++;
      }
      left++;
    }
  }

  return matrix;
}

