// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => arc.todo("variableLengthQuantity.decode");
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit (0x80) for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    if ((byte & 0x80) === 0) {
      // Last byte
      if (bitsCollected === 0) {
        // Single byte number
        result.push(byte);
      } else {
        // Multi-byte number finished
        // We need to reconstruct the number.
        // The bytes were collected in order: first byte (MSB) ... last byte (LSB).
        // However, in the loop, 'currentNumber' accumulates them as:
        // currentNumber = (currentNumber << 7) | byte
        // So 'currentNumber' already holds the correct value if we shift correctly.
        // Let's re-verify the logic inside the 'else' block.

        // Actually, the previous logic was flawed in how it reconstructed.
        // Let's use BigInt for safety and clarity during reconstruction, or fix the shift logic.

        // Correct reconstruction logic:
        // The value is built by shifting the accumulator left by 7 and adding the new byte.
        // Since we did exactly that in the 'else' block (currentNumber = (currentNumber << 7) | byte),
        // the value is already in 'currentNumber'.

        let value = currentNumber;
        if (value > 0xFFFFFFFF) {
          throw new Error("Decoded number exceeds 32-bit unsigned integer range");
        }
        result.push(value);
      }
      currentNumber = 0;
      bitsCollected = 0;
    } else {
      // Not the last byte
      bitsCollected++;
      // Shift current number left by 7 and add the new byte
      currentNumber = (currentNumber << 7) | byte;

      // Check for overflow: if we have collected 5 bytes (40 bits) and the continuation bit is still set,
      // it means the number is too large for 32 bits.
      // 5 bytes * 7 bits = 35 bits. If the 5th byte has the continuation bit set, we need a 6th byte.
      // 6 bytes * 7 bits = 42 bits. This definitely exceeds 32 bits.
      // So if bitsCollected reaches 5 and the next byte also has the continuation bit, we overflow.
      // But we check here: if we have already collected 5 bytes (meaning we are about to process the 6th byte),
      // and the current byte (which caused bitsCollected to become 5) had the continuation bit set,
      // then we are in trouble if we continue.
      // Actually, simpler check: if bitsCollected > 5, we have definitely exceeded 32 bits (5*7=35 > 32).
      // But we must ensure we don't throw prematurely if the sequence ends exactly at 32 bits (5 bytes).
      // 32 bits requires 5 bytes (49 bits capacity, but we only use 32).
      // If bitsCollected is 5, we have 35 bits of data. If the 5th byte had continuation bit set, we need more.
      // So if bitsCollected > 5, it's an error.
      if (bitsCollected > 5) {
        throw new Error("Decoded number exceeds 32-bit unsigned integer range");
      }
    }
  }

  // If we ended without finishing a number (bitsCollected > 0), it's an error
  if (bitsCollected > 0) {
    throw new Error("Incomplete sequence: missing final byte with continuation bit clear");
  }

  return result;
}

