// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => arc.todo("wordy.answer");
// @openarc:end wordy.answer

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Invalid question");
  }

  // Remove surrounding whitespace and the fixed prefix/suffix
  const trimmed = question.trim();
  if (!trimmed.startsWith("What is")) {
    throw new Error("Unknown operation");
  }

  // Extract the expression part between "What is" and "?"
  const expression = trimmed
    .substring(7) // length of "What is"
    .trim()
    .replace(/\?$/, "");

  if (!expression) {
    throw new Error("Syntax error");
  }

  // Tokenize the expression
  const tokens = tokenize(expression);

  // Parse and evaluate
  let result: number;
  let index = 0;

  // First number
  const firstToken = tokens[index++];
  if (!isNumber(firstToken)) {
    throw new Error("Syntax error");
  }
  result = parseFloat(firstToken);

  // Process remaining tokens
  while (index < tokens.length) {
    const op = tokens[index++];
    if (!isOperator(op)) {
      throw new Error("Unknown operation");
    }

    if (index >= tokens.length) {
      throw new Error("Syntax error");
    }

    const numToken = tokens[index++];
    if (!isNumber(numToken)) {
      throw new Error("Syntax error");
    }
    const num = parseFloat(numToken);

    switch (op) {
      case "plus":
        result += num;
        break;
      case "minus":
        result -= num;
        break;
      case "multiplied":
        if (tokens[index - 2] !== "by") {
          throw new Error("Unknown operation");
        }
        result *= num;
        break;
      case "divided":
        if (tokens[index - 2] !== "by") {
          throw new Error("Unknown operation");
        }
        if (num === 0) {
          throw new Error("Division by zero");
        }
        result /= num;
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  // Check for remaining tokens that might indicate an error (e.g., extra words)
  if (index < tokens.length) {
    throw new Error("Syntax error");
  }

  // Return integer result as per requirements
  return Math.round(result);
}

function tokenize(input: string): string[] {
  const tokens: string[] = [];
  let current = "";
  let i = 0;

  while (i < input.length) {
    const char = input[i];

    if (/\s/.test(char)) {
      if (current) {
        tokens.push(current);
        current = "";
      }
      i++;
      continue;
    }

    if (char === "?") {
      if (current) {
        tokens.push(current);
        current = "";
      }
      break;
    }

    // Handle negative numbers: if we see a minus sign and the previous token is a number or start of string
    if (char === "-" && (tokens.length === 0 || isNumber(tokens[tokens.length - 1]))) {
      current += char;
      i++;
      continue;
    }

    // Handle operators
    if (
      char === "+" ||
      char === "-" ||
      char === "*" ||
      char === "/"
    ) {
      if (current) {
        tokens.push(current);
        current = "";
      }
      // Map single char operators to word forms for consistency
      if (char === "+") {
        tokens.push("plus");
      } else if (char === "-") {
        tokens.push("minus");
      } else if (char === "*") {
        tokens.push("multiplied");
      } else if (char === "/") {
        tokens.push("divided");
      }
      i++;
      continue;
    }

    // Handle "by" keyword
    if (char === "b" && input.substring(i, i + 2) === "by") {
      if (current) {
        tokens.push(current);
        current = "";
      }
      tokens.push("by");
      i += 2;
      continue;
    }

    // Regular character
    current += char;
    i++;
  }

  if (current) {
    tokens.push(current);
  }

  return tokens;
}

function isNumber(token: string): boolean {
  if (!token) return false;
  // Match optional negative sign followed by digits
  return /^-?\d+$/.test(token);
}

function isOperator(token: string): boolean {
  return (
    token === "plus" ||
    token === "minus" ||
    token === "multiplied" ||
    token === "divided" ||
    token === "by"
  );
}

