// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const translateWord = (word: string): string => {
    if (vowels.has(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
      return word + 'ay';
    }
    let i = 0;
    while (i < word.length) {
      if (word[i] === 'y' && i > 0) {
        break;
      }
      if (word[i] === 'q' && i + 1 < word.length && word[i + 1] === 'u') {
        i += 2;
        continue;
      }
      if (vowels.has(word[i])) {
        break;
      }
      i++;
    }
    return word.slice(i) + word.slice(0, i) + 'ay';
  };
  return phrase.split(' ').map(translateWord).join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  if (!phrase) return phrase;

  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);

  const translateWord = (word: string): string => {
    // Rule 1: Starts with vowel, "xr", or "yt"
    if (vowels.has(word[0]) || word.startsWith('xr') || word.startsWith('yt')) {
      return word + 'ay';
    }

    let i = 0;
    const len = word.length;

    // Check for "qu" at the start (Rule 3)
    if (word.startsWith('qu')) {
      return word.slice(2) + 'qu' + 'ay';
    }

    // Find the split point for consonants
    while (i < len) {
      const char = word[i];
      const nextChar = word[i + 1];

      // Rule 4: Consonants followed by 'y' (treat 'y' as vowel if preceded by consonants)
      if (char !== undefined && !vowels.has(char) && nextChar === 'y') {
        break;
      }

      // Rule 3: Check for 'qu' inside the consonant cluster
      if (char === 'q' && nextChar === 'u') {
        i += 2;
        break;
      }

      // Rule 1 & 2: Found a vowel (or end of string)
      if (vowels.has(char)) {
        break;
      }

      i++;
    }

    // If we reached the end without finding a vowel or special case
    if (i === len) {
      return word + 'ay';
    }

    return word.slice(i) + word.slice(0, i) + 'ay';
  };

  return phrase
    .split(' ')
    .map(translateWord)
    .join(' ');
}

