// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const n = rows.length;
  if (n === 0) return 0;
  const m = rows[0].length;
  if (m === 0) return 0;
  const grid = rows.map((row, r) => row.split(''));
  const isCorner = (r: number, c: number) => {
      if (r < 0 || r >= n || c < 0 || c >= m) return false;
      const ch = grid[r][c];
      return ch === '+';
    };
  const isTop = (r: number, c: number) => {
      if (r < 0 || r >= n || c < 0 || c >= m) return false;
      return grid[r][c] === '-';
    };
  const isBottom = (r: number, c: number) => {
      if (r < 0 || r >= n || c < 0 || c >= m) return false;
      return grid[r][c] === '-';
    };
  const isLeft = (r: number, c: number) => {
      if (r < 0 || r >= n || c < 0 || c >= m) return false;
      return grid[r][c] === '|';
    };
  const isRight = (r: number, c: number) => {
      if (r < 0 || r >= n || c < 0 || c >= m) return false;
      return grid[r][c] === '|';
    };
  let count = 0;
  for (let r1 = 0; r1 < n; r1++) {
      for (let c1 = 0; c1 < m; c1++) {
        if (!isCorner(r1, c1)) continue;
        for (let r2 = r1; r2 < n; r2++) {
          for (let c2 = c1; c2 < m; c2++) {
            if (r1 === r2 && c1 === c2) continue;
            if (isCorner(r1, c2) && isCorner(r2, c1) && isCorner(r2, c2)) {
              let valid = true;
              for (let c = c1; c <= c2; c++) {
                if (!isTop(r1, c) || !isBottom(r2, c)) valid = false;
              }
              for (let r = r1; r <= r2; r++) {
                if (!isLeft(r, c1) || !isRight(r, c2)) valid = false;
              }
              if (valid) count++;
            }
          }
        }
      }
    }
  return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (!rows || rows.length === 0) return 0;

  const numCols = rows[0].length;
  if (numCols === 0) return 0;

  // Validate that all rows have the same length as the first row
  for (const row of rows) {
    if (row.length !== numCols) {
      throw new Error("All rows must have the same length");
    }
  }

  let rectangleCount = 0;

  // Iterate over all possible top-left corners (r1, c1)
  for (let r1 = 0; r1 < rows.length; r1++) {
    for (let c1 = 0; c1 < numCols; c1++) {
      // Top-left corner must be '+'
      if (rows[r1][c1] !== '+') continue;

      // Iterate over all possible bottom-right corners (r2, c2)
      for (let r2 = r1; r2 < rows.length; r2++) {
        for (let c2 = c1; c2 < numCols; c2++) {
          // Bottom-right corner must be '+'
          if (rows[r2][c2] !== '+') continue;

          // Check if the other two corners are '+'
          if (rows[r1][c2] !== '+' || rows[r2][c1] !== '+') continue;

          // Check if all four sides are valid
          let isRectangle = true;

          // Check top and bottom horizontal sides
          for (let c = c1 + 1; c < c2; c++) {
            if (rows[r1][c] !== '-' && rows[r1][c] !== '+') {
              isRectangle = false;
              break;
            }
            if (rows[r2][c] !== '-' && rows[r2][c] !== '+') {
              isRectangle = false;
              break;
            }
          }

          if (!isRectangle) continue;

          // Check left and right vertical sides
          for (let r = r1 + 1; r < r2; r++) {
            if (rows[r][c1] !== '|' && rows[r][c1] !== '+') {
              isRectangle = false;
              break;
            }
            if (rows[r][c2] !== '|' && rows[r][c2] !== '+') {
              isRectangle = false;
              break;
            }
          }

          if (isRectangle) {
            rectangleCount++;
          }
        }
      }
    }
  }

  return rectangleCount;
}

