// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => arc.todo("wordy.answer");
// @openarc:end wordy.answer

export function answer(question: string): number {
  if (!question || typeof question !== "string") {
    throw new Error("Unknown operation");
  }

  const trimmed = question.trim();
  if (!trimmed.endsWith("?")) {
    throw new Error("Unknown operation");
  }

  const content = trimmed.slice(0, -1).trim();
  if (!content.startsWith("What is")) {
    throw new Error("Unknown operation");
  }

  const expression = content.slice(6).trim();
  if (!expression) {
    throw new Error("Unknown operation");
  }

  // Tokenize: split by spaces, filter empty strings
  const rawTokens = expression.split(/\s+/).filter(t => t.length > 0);
  if (rawTokens.length === 0) {
    throw new Error("Unknown operation");
  }

  const parsed: Array<{ type: "num" | "op"; value: number | string }> = [];

  for (const token of rawTokens) {
    // Check if token is a valid integer (including negative)
    if (/^-?\d+$/.test(token)) {
      parsed.push({ type: "num", value: parseInt(token, 10) });
    } else {
      // It must be an operator
      const opMap: Record<string, string> = {
        plus: "+",
        minus: "-",
        multiplied: "*",
        divided: "/",
      };

      const op = opMap[token];
      if (!op) {
        throw new Error("Unknown operation");
      }
      parsed.push({ type: "op", value: op });
    }
  }

  // Validate structure: must start and end with a number
  if (parsed.length === 0 || parsed[0].type !== "num" || parsed[parsed.length - 1].type !== "num") {
    throw new Error("Unknown operation");
  }

  // Check for consecutive operators or missing operands (e.g., "plus plus")
  for (let i = 0; i < parsed.length - 1; i++) {
    if (parsed[i].type === parsed[i + 1].type) {
      throw new Error("Unknown operation");
    }
  }

  // Evaluate left-to-right
  let result = parsed[0].value as number;

  for (let i = 1; i < parsed.length; i += 2) {
    const op = parsed[i].value as string;
    const nextNum = parsed[i + 1].value as number;

    switch (op) {
      case "+":
        result += nextNum;
        break;
      case "-":
        result -= nextNum;
        break;
      case "*":
        result *= nextNum;
        break;
      case "/":
        if (nextNum === 0) {
          throw new Error("Unknown operation");
        }
        result = Math.trunc(result / nextNum);
        break;
      default:
        throw new Error("Unknown operation");
    }
  }

  return result;
}

