export function makeDiamond(character: string): string {
  const charCode = character.charCodeAt(0);
  const targetChar = character.toUpperCase();
  const startChar = "A".charCodeAt(0);

  if (charCode < startChar || charCode > startChar + 25) {
    throw new Error("Input must be a single uppercase letter from A to Z");
  }

  const n = charCode - startChar; // 0 for 'A', 2 for 'C', etc.
  const totalRows = 2 * n + 1;
  const halfWidth = n; // Number of steps from center to edge (excluding center)

  const lines: string[] = [];

  // Generate top half including the middle row
  for (let i = 0; i <= n; i++) {
    const currentChar = String.fromCharCode(startChar + i);
    const outerSpaces = " ".repeat(n - i);

    if (i === 0) {
      // Special case for 'A': just one letter, no inner spaces
      lines.push(outerSpaces + currentChar + outerSpaces);
    } else {
      // For other letters: outer spaces + letter + inner spaces + letter + outer spaces
      const innerSpaces = " ".repeat(2 * i - 1);
      lines.push(outerSpaces + currentChar + innerSpaces + currentChar + outerSpaces);
    }
  }

  // Generate bottom half by reversing the top half (excluding the middle row)
  const topHalf = lines.slice(0, n + 1);
  const bottomHalf = topHalf.slice(0, -1).reverse();

  return [...topHalf, ...bottomHalf].join("\n") + "\n";
}

