export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  if (cols === 0) return field;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count > 0 ? count.toString() : ' ');
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  if (field.length === 0) {
    return [];
  }

  const rows = field.length;
  const cols = field[0].length;
  const result: string[] = [];

  for (let i = 0; i < rows; i++) {
    let newRow = "";
    for (let j = 0; j < cols; j++) {
      const cell = field[i][j];

      if (cell === '*') {
        newRow += '*';
        continue;
      }

      let mineCount = 0;

      // Check all 8 adjacent cells
      for (let di = -1; di <= 1; di++) {
        for (let dj = -1; dj <= 1; dj++) {
          if (di === 0 && dj === 0) continue;

          const ni = i + di;
          const nj = j + dj;

          if (
            ni >= 0 &&
            ni < rows &&
            nj >= 0 &&
            nj < cols &&
            field[ni][nj] === '*'
          ) {
            mineCount++;
          }
        }
      }

      if (mineCount > 0) {
        newRow += mineCount.toString();
      } else {
        newRow += ' ';
      }
    }
    result.push(newRow);
  }

  return result;
}

