// @openarc:begin twelveDays.recite
export const recite: ReciteFn = (startVerse, endVerse) => arc.todo("twelveDays.recite");
// @openarc:end twelveDays.recite

export function recite(startVerse: number, endVerse: number): string {
  if (startVerse < 1 || endVerse > 12 || startVerse > endVerse) {
    throw new Error("Invalid verse range");
  }

  const days = [
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
  ];

  const gifts = [
    "a Partridge in a Pear Tree",
    "two Turtle Doves",
    "three French Hens",
    "four Calling Birds",
    "five Gold Rings",
    "six Geese-a-Laying",
    "seven Swans-a-Swimming",
    "eight Maids-a-Milking",
    "nine Ladies Dancing",
    "ten Lords-a-Leaping",
    "eleven Pipers Piping",
    "twelve Drummers Drumming",
  ];

  const verses: string[] = [];

  for (let i = startVerse; i <= endVerse; i++) {
    const currentDayIndex = i - 1;
    let verseText = `On the ${days[currentDayIndex]} day of Christmas my true love gave to me: `;

    const constructedGifts: string[] = [];
    for (let j = currentDayIndex; j >= 0; j--) {
      const giftText = gifts[j];
      if (j === 0 && currentDayIndex > 0) {
        constructedGifts.push(`and ${giftText}`);
      } else {
        constructedGifts.push(giftText);
      }
    }

    verseText += constructedGifts.join(", ");
    verseText += "\n";
    verses.push(verseText);
  }

  return verses.join("");
}

