// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  if (inputBase < 2 || outputBase < 2) throw new Error('Wrong input base');
  if (inputBase > 36 || outputBase > 36) throw new Error('Wrong input base');
  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase) throw new Error('Wrong digit');
  }
  let value = 0;
  for (const digit of digits) {
    value = value * inputBase + digit;
  }
  if (value === 0) return [0];
  const result: number[] = [];
  while (value > 0) {
    result.unshift(value % outputBase);
    value = Math.floor(value / outputBase);
  }
  return result;
};
// @openarc:end allYourBase.convert

export function convert(digits: number[], inputBase: number, outputBase: number): number[] {
  // Validate inputBase
  if (inputBase < 2 || !Number.isInteger(inputBase)) {
    throw new Error("Wrong input base");
  }

  // Validate outputBase
  if (outputBase < 2 || !Number.isInteger(outputBase)) {
    throw new Error("Wrong output base");
  }

  // Validate digits array
  if (digits.length === 0) {
    throw new Error("Input has wrong format");
  }

  // Check for leading zeros (unless the number is just [0])
  if (digits.length > 1 && digits[0] === 0) {
    throw new Error("Input has wrong format");
  }

  // Check each digit validity
  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase || !Number.isInteger(digit)) {
      throw new Error("Input has wrong format");
    }
  }

  // Convert input digits to a decimal (base 10) number
  let decimalValue = 0;
  for (const digit of digits) {
    decimalValue = decimalValue * inputBase + digit;
  }

  // Handle the case where the value is 0
  if (decimalValue === 0) {
    return [0];
  }

  // Convert decimal value to output base digits
  const outputDigits: number[] = [];
  while (decimalValue > 0) {
    outputDigits.unshift(decimalValue % outputBase);
    decimalValue = Math.floor(decimalValue / outputBase);
  }

  return outputDigits;
}

