export function verse(n: number): string {
  if (Number.isNaN(n) || !Number.isInteger(n) || n < 1 || n > 8) {
    throw new Error("Invalid verse number");
  }

  const animals = [
    "fly",
    "spider",
    "bird",
    "cat",
    "dog",
    "goat",
    "cow",
    "horse",
  ];

  const comments = [
    "",
    "It wriggled and jiggled and tickled inside her.",
    "How absurd to swallow a bird!",
    "Imagine that, to swallow a cat!",
    "What a hog, to swallow a dog!",
    "Just opened her throat and swallowed a goat!",
    "I don't know how she swallowed a cow!",
    "She's dead, of course!",
  ];

  let lines: string[] = [];

  // First line
  lines.push(`I know an old lady who swallowed a ${animals[n - 1]}.`);

  // If it's not the fly (index 0), add the comment
  if (n > 1) {
    lines.push(comments[n - 1]);
  }

  // The cumulative part
  if (n > 1) {
    for (let i = n - 1; i > 0; i--) {
      let line = `She swallowed the ${animals[i]} to catch the ${animals[i - 1]}`;
      // Special case for spider: add the description
      if (i - 1 === 1) {
        line += " that wriggled and jiggled and tickled inside her";
      }
      line += ".";
      lines.push(line);
    }
  }

  // The last line for all verses except the horse
  if (n < 8) {
    lines.push("I don't know why she swallowed the fly. Perhaps she'll die.");
  }

  return lines.join("\n") + "\n";
}

export function verses(start: number, end: number): string {
  if (Number.isNaN(start) || Number.isNaN(end)) {
    throw new Error("Invalid start or end number");
  }
  if (!Number.isInteger(start) || !Number.isInteger(end)) {
    throw new Error("Start and end must be integers");
  }
  if (start < 1 || end > 8 || start > end) {
    throw new Error("Invalid range");
  }

  return Array.from({ length: end - start + 1 }, (_, i) =>
    verse(start + i)
  ).join("\n");
}

