export function encode(numbers: number[]): number[] {
  const result: number[] = [];

  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range");
    }

    if (num === 0) {
      result.push(0);
      continue;
    }

    const bytes: number[] = [];
    let n = num;

    while (n > 0) {
      const byte = n & 0x7F;
      n >>= 7;
      bytes.unshift(byte);
    }

    // Set continuation bit for all bytes except the last one
    for (let i = 0; i < bytes.length - 1; i++) {
      bytes[i] |= 0x80;
    }

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let currentNumber = 0;
  let bitsCollected = 0;

  for (const byte of bytes) {
    // Validate byte range
    if (byte < 0 || byte > 255) {
      throw new Error("Invalid byte value");
    }

    // Extract the 7 data bits
    const data = byte & 0x7F;

    // Shift the current number left by 7 and add the new data
    currentNumber = (currentNumber << 7) | data;
    bitsCollected++;

    // Check if this is the last byte (continuation bit is 0)
    if ((byte & 0x80) === 0) {
      // Validate range for 32-bit unsigned integer
      if (currentNumber > 0xFFFFFFFF) {
        throw new Error("Decoded number out of range");
      }
      result.push(currentNumber);
      currentNumber = 0;
      bitsCollected = 0;
    } else {
      // Check for too many bytes (more than 5 continuation bytes means > 32 bits)
      if (bitsCollected > 5) {
        throw new Error("Too many bytes for a 32-bit integer");
      }
    }
  }

  // If we ended without finishing a number (bitsCollected > 0), it's an error
  if (bitsCollected !== 0) {
    throw new Error("Incomplete sequence");
  }

  return result;
}

