export const ofSize: OfSizeFn = (size) => {
  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
    let num = 1;
    let top = 0, bottom = size - 1, left = 0, right = size - 1;

    while (top <= bottom && left <= right) {
      for (let i = left; i <= right; i++) {
        matrix[top][i] = num++;
      }
      top++;

      for (let i = top; i <= bottom; i++) {
        matrix[i][right] = num++;
      }
      right--;

      if (top <= bottom) {
        for (let i = right; i >= left; i--) {
          matrix[bottom][i] = num++;
        }
        bottom--;
      }

      if (left <= right) {
        for (let i = bottom; i >= top; i--) {
          matrix[i][left] = num++;
        }
        left++;
      }
    }

    return matrix;
};
// @openarc:end spiralMatrix.ofSize

export function ofSize(size: number): number[][] {
  if (size < 0) {
    throw new Error("Size must be a non-negative integer");
  }

  const matrix: number[][] = Array(size).fill(0).map(() => Array(size).fill(0));
  let num = 1;
  let top = 0, bottom = size - 1, left = 0, right = size - 1;

  while (num <= size * size) {
    // Fill top row
    for (let i = left; i <= right && num <= size * size; i++) {
      matrix[top][i] = num++;
    }
    top++;

    // Fill right column
    for (let i = top; i <= bottom && num <= size * size; i++) {
      matrix[i][right] = num++;
    }
    right--;

    // Fill bottom row
    for (let i = right; i >= left && num <= size * size; i--) {
      matrix[bottom][i] = num++;
    }
    bottom--;

    // Fill left column
    for (let i = bottom; i >= top && num <= size * size; i--) {
      matrix[i][left] = num++;
    }
    left++;
  }

  return matrix;
}

