// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => {
  const numberWords = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']; const operationWords = {'plus': '+', 'minus': '-', 'multiplied by': '*', 'divided by': '/'}; const parseNumber = (word: string): number => { if (numberWords.includes(word.toLowerCase())) { return numberWords.indexOf(word.toLowerCase()); } return parseInt(word, 10); }; const tokens = question.toLowerCase().replace(/^what is /, '').split(/\s+/); if (tokens.length === 1) { return parseNumber(tokens[0]); } let result = parseNumber(tokens[0]); for (let i = 1; i < tokens.length; i += 2) { const operation = tokens[i]; const operand = parseNumber(tokens[i + 1]); if (!(operation in operationWords)) { throw new Error('Unsupported operation'); } if (isNaN(operand)) { throw new Error('Invalid number'); } switch (operationWords[operation as keyof typeof operationWords]) { case '+': result += operand; break; case '-': result -= operand; break; case '*': result *= operand; break; case '/': if (operand === 0) { throw new Error('Division by zero'); } result = Math.floor(result / operand); break; } } return result;
};
// @openarc:end wordy.answer

export function answer(question: string): number {
  const validOperations = ['plus', 'minus', 'multiplied by', 'divided by'];
  const regex = /^What is (-?\d+)( (plus|minus|multiplied by|divided by) -?\d+)+(\?)?$/;
  const match = question.match(regex);

  if (!match) {
    if (question.startsWith('What is ')) {
      const numberMatch = question.match(/^What is (-?\d+)\?$/);
      if (numberMatch) {
        return parseInt(numberMatch[1], 10);
      }
      throw new Error('Unsupported operation');
    }
    throw new Error('Invalid syntax');
  }

  let result = parseInt(match[1], 10);
  const operations = match[0].split(' ').slice(2, -1);

  for (let i = 0; i < operations.length; i += 2) {
    const operation = operations[i];
    const number = parseInt(operations[i + 1], 10);

    if (!validOperations.includes(operation)) {
      throw new Error('Unsupported operation');
    }

    switch (operation) {
      case 'plus':
        result += number;
        break;
      case 'minus':
        result -= number;
        break;
      case 'multiplied by':
        result *= number;
        break;
      case 'divided by':
        if (number === 0) {
          throw new Error('Division by zero');
        }
        result = Math.floor(result / number);
        break;
    }
  }

  return result;
}

