// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  const words = phrase.split(' ');
  const translatedWords = words.map(word => {
    if (/^[aeiou]|^xr|^yt/.test(word)) {
      return word + 'ay';
    } else if (/^[^aeiou]+/.test(word)) {
      const match = word.match(/^[^aeiou]+/);
      return match ? word.slice(match[0].length) + match[0] + 'ay' : word;
    } else if (/qu$/.test(word)) {
      return word.slice(0, -2) + 'ay';
    } else if (/y$/.test(word)) {
      const match = word.match(/[^aeiou]*y/);
      return match ? word.slice(match[0].length) + match[0] + 'ay' : word;
    }
    return word;
  });
  return translatedWords.join(' ');
};
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  const words = phrase.split(' ');
  const translatedWords = words.map(word => translateWord(word));
  return translatedWords.join(' ');
}

function translateWord(word: string): string {
  if (startsWithVowel(word) || word.startsWith('xr') || word.startsWith('yt')) {
    return word + 'ay';
  }

  if (startsWithConsonants(word)) {
    const consonantCluster = getConsonantCluster(word);
    return word.slice(consonantCluster.length) + consonantCluster + 'ay';
  }

  if (word.includes('qu')) {
    const quIndex = word.indexOf('qu');
    return word.slice(quIndex + 2) + word.slice(0, quIndex + 2) + 'ay';
  }

  if (word.includes('y')) {
    const yIndex = word.indexOf('y');
    return word.slice(yIndex) + word.slice(0, yIndex) + 'ay';
  }

  return word;
}

function startsWithVowel(word: string): boolean {
  return /^[aeiou]/i.test(word);
}

function startsWithConsonants(word: string): boolean {
  return /^[^aeiou]/i.test(word);
}

function getConsonantCluster(word: string): string {
  const match = word.match(/^[^aeiou]+/i);
  return match ? match[0] : '';
}

