// @openarc:begin sumOfMultiples.sum
export const sum: SumFn = (factors, limit) => {
  const multiples = new Set<number>();
    factors.forEach(factor => {
      for (let i = factor; i < limit; i += factor) {
        multiples.add(i);
      }
    });
    return Array.from(multiples).reduce((sum, num) => sum + num, 0);
};
// @openarc:end sumOfMultiples.sum

export function sum(factors: number[], limit: number): number {
  const uniqueMultiples = new Set<number>();

  for (const factor of factors) {
    if (factor > 0) {
      for (let i = factor; i < limit; i += factor) {
        uniqueMultiples.add(i);
      }
    }
  }

  let totalSum = 0;
  for (const multiple of uniqueMultiples) {
    totalSum += multiple;
  }

  return totalSum;
}

