export function transpose(rows: string[]): string[] {
  if (rows.length === 0) return [];

  // Find the maximum length of the rows
  const maxLength = Math.max(...rows.map(row => row.length));

  // Pad rows with spaces to the left to make them all the same length
  const paddedRows = rows.map(row => row.padStart(maxLength));

  // Initialize the transposed array
  const transposed: string[] = [];

  // Perform the transpose
  for (let i = 0; i < maxLength; i++) {
    let newRow = '';
    for (let j = 0; j < paddedRows.length; j++) {
      newRow += paddedRows[j][i];
    }
    // Trim trailing spaces from the new row
    transposed.push(newRow.trimEnd());
  }

  return transposed;
}

