      value >>>= 7; // Shift right by 7 bits

      if (value !== 0) {
        byte |= 0x80; // Set the continuation bit
      }

      bytes.push(byte);
    } while (value !== 0);

    result.push(...bytes);
  }

  return result;
}

export function decode(bytes: number[]): number[] {
  const result: number[] = [];
  let value = 0;
  let shift = 0;

  for (const byte of bytes) {
    value |= (byte & 0x7F) << shift;

    if ((byte & 0x80) === 0) {
      result.push(value);
      value = 0;
      shift = 0;
    } else {
      shift += 7;
    }
  }

  return result;
}

