// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  let count = 0;
    const n = rows.length;
    if (n === 0) return 0;
    const m = rows[0].length;
    const heights = new Array(m).fill(0);
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < m; j++) {
        if (rows[i][j] === ' ') {
          heights[j]++;
        } else {
          heights[j] = 0;
        }
      }
      for (let j = 0; j < m; j++) {
        if (rows[i][j] === '+') {
          for (let k = j + 1; k < m; k++) {
            if (rows[i][k] === '+') {
              let minHeight = Infinity;
              for (let l = j + 1; l < k; l++) {
                minHeight = Math.min(minHeight, heights[l]);
              }
              count += minHeight;
            }
          }
        }
      }
    }
    return count;
};
// @openarc:end rectangles.count

export function count(rows: string[]): number {
  if (rows.length === 0 || rows[0].length === 0) return 0;

  const height = rows.length;
  const width = rows[0].length;
  const grid = rows.map(row => row.split(''));
  const visited = Array.from({ length: height }, () => Array(width).fill(false));

  function dfs(x: number, y: number): void {
    if (x < 0 || x >= width || y < 0 || y >= height || visited[y][x] || grid[y][x] !== ' ') {
      return;
    }
    visited[y][x] = true;
    dfs(x + 1, y);
    dfs(x - 1, y);
    dfs(x, y + 1);
    dfs(x, y - 1);
  }

  let rectangleCount = 0;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!visited[y][x] && grid[y][x] === ' ') {
        dfs(x, y);
        rectangleCount++;
      }
    }
  }

  return rectangleCount;
}

