// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  const result = [];
  for (const number of numbers) {
      let value = number;
      do {
        let byte = value & 0x7F;
        value >>>= 7;
        if (value !== 0) {
          byte |= 0x80;
        }
        result.push(byte);
      } while (value !== 0);
    }
  return result;
};
